double absorbProb(vector<vector<double>>& P, int start, int target) {
    int n = P.size(); vector<int> T, idx(n, -1); for (int i = 0; i < n; i++) if (P[i][i] != 1.0) { idx[i] = T.size(); T.push_back(i); }
    if (idx[start] < 0) return start == target ? 1.0 : 0.0; int m = T.size();
    vector<vector<double>> A(m, vector<double>(m + 1));
    for (int a = 0; a < m; a++) { for (int b = 0; b < m; b++) A[a][b] = (a == b) - P[T[a]][T[b]]; A[a][m] = P[T[a]][target]; }
    for (int c = 0; c < m; c++) { int piv = c; for (int r = c; r < m; r++) if (fabs(A[r][c]) > fabs(A[piv][c])) piv = r; swap(A[c], A[piv]);
        for (int r = 0; r < m; r++) if (r != c && A[r][c] != 0) { double f = A[r][c] / A[c][c]; for (int k = c; k <= m; k++) A[r][k] -= f * A[c][k]; } }
    int s = idx[start]; return A[s][m] / A[s][s];
}
